mapper.select:
SELECT t1.id, t1.sku_sn, concat(t2.name, ' ', t1.name) skuName, ifnull(t1.pic_url, t2.pic_url) pic_url, t1.supply_price, t1.retail_price, t1.market_price marketPrice, t1.stock, t2.name as spuName, t2.spu_type spuType, t2.id spuId, t1.supplier_id supplierId, t2.forbidden_area_id as forbiddenAreaId, t2.freight_template_id as freightTemplateId FROM pms_sku t1 INNER JOIN pms_spu t2 ON t1.spu_id = t2.id
t2.status = 1 and t2.deleted = 0
AND t1.name like concat('%',#{queryParams.keywords},'%')
AND t2.category_id =#{queryParams.categoryId}
AND t2.spu_type = #{queryParams.spuType}
AND t2.audit_status = #{queryParams.auditStatus}
